/**
 * OGlobe3D.scene - 内部 3D 实现,由 OGlobe3D 通过 dynamic import 按需加载。
 *
 * 不直接 export 给最终用户,避免 main bundle 包含 three.js。
 */
'use client';

import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Sphere } from '@react-three/drei';
import { useMemo, useRef, useState } from 'react';
import * as THREE from 'three';
import type { OGlobe3DData } from './OGlobe3D.types';

const GLOBE_RADIUS = 1;

function latLngToVec3(lat: number, lng: number, r = GLOBE_RADIUS): THREE.Vector3 {
  const phi = (90 - lat) * (Math.PI / 180);
  const theta = (lng + 180) * (Math.PI / 180);
  return new THREE.Vector3(
    -(r * Math.sin(phi) * Math.cos(theta)),
    r * Math.cos(phi),
    r * Math.sin(phi) * Math.sin(theta)
  );
}

function Marker({
  position,
  value,
  label,
  color,
  onHover,
}: {
  position: THREE.Vector3;
  value: number;
  label: string;
  color: string;
  onHover: (label: string | null) => void;
}) {
  const ref = useRef<THREE.Mesh>(null);
  const size = 0.012 + Math.min(value / 100, 1) * 0.035;

  useFrame((state) => {
    if (!ref.current) return;
    const t = state.clock.elapsedTime;
    const scale = 1 + Math.sin(t * 2 + position.x) * 0.15;
    ref.current.scale.set(scale, scale, scale);
  });

  return (
    <mesh
      ref={ref}
      position={position}
      onPointerOver={(e) => {
        e.stopPropagation();
        onHover(label);
      }}
      onPointerOut={() => onHover(null)}
    >
      <sphereGeometry args={[size, 12, 12]} />
      <meshBasicMaterial color={color} transparent opacity={0.9} />
    </mesh>
  );
}

function Arc({
  from,
  to,
  color,
}: {
  from: THREE.Vector3;
  to: THREE.Vector3;
  color: string;
}) {
  const curve = useMemo(() => {
    const mid = from.clone().lerp(to, 0.5).normalize().multiplyScalar(GLOBE_RADIUS * 1.4);
    return new THREE.QuadraticBezierCurve3(from, mid, to);
  }, [from, to]);

  const points = useMemo(() => curve.getPoints(48), [curve]);
  const geometry = useMemo(() => new THREE.BufferGeometry().setFromPoints(points), [points]);

  return (
    <line>
      <primitive object={geometry} attach="geometry" />
      <lineBasicMaterial color={color} transparent opacity={0.4} />
    </line>
  );
}

function GlobeMesh({ autoRotate, globeColor }: { autoRotate: boolean; globeColor: string }) {
  const ref = useRef<THREE.Mesh>(null);
  useFrame((_, delta) => {
    if (autoRotate && ref.current) {
      ref.current.rotation.y += delta * 0.08;
    }
  });

  return (
    <Sphere ref={ref} args={[GLOBE_RADIUS, 48, 48]}>
      <meshBasicMaterial
        color={globeColor}
        wireframe
        wireframeLinewidth={1}
        transparent
        opacity={0.35}
      />
    </Sphere>
  );
}

export interface SceneProps {
  data: OGlobe3DData;
  autoRotate: boolean;
  interactive: boolean;
  markerColor: string;
  arcColor: string;
  globeColor: string;
}

export function GlobeScene({ data, autoRotate, interactive, markerColor, arcColor, globeColor }: SceneProps) {
  const [hoverLabel, setHoverLabel] = useState<string | null>(null);

  const markers = useMemo(
    () =>
      data.markers.map((m, i) => ({
        ...m,
        key: `m-${i}`,
        position: latLngToVec3(m.lat, m.lng, GLOBE_RADIUS * 1.02),
      })),
    [data.markers]
  );

  const arcs = useMemo(
    () =>
      (data.arcs ?? []).map((a, i) => ({
        key: `a-${i}`,
        from: latLngToVec3(a.from[0], a.from[1]),
        to: latLngToVec3(a.to[0], a.to[1]),
        value: a.value,
      })),
    [data.arcs]
  );

  return (
    <div className="relative w-full h-full @container">
      <Canvas camera={{ position: [0, 0, 3], fov: 45 }} dpr={[1, 2]}>
        <ambientLight intensity={0.6} />
        <pointLight position={[5, 5, 5]} intensity={0.8} />
        <GlobeMesh autoRotate={autoRotate} globeColor={globeColor} />
        <group>
          {markers.map((m) => (
            <Marker
              key={m.key}
              position={m.position}
              value={m.value}
              label={m.label}
              color={markerColor}
              onHover={setHoverLabel}
            />
          ))}
        </group>
        <group>
          {arcs.map((a) => (
            <Arc key={a.key} from={a.from} to={a.to} color={arcColor} />
          ))}
        </group>
        {interactive ? (
          <OrbitControls
            enablePan={false}
            enableZoom={true}
            autoRotate={false}
            minDistance={1.8}
            maxDistance={5}
          />
        ) : null}
      </Canvas>

      {hoverLabel ? (
        <div className="absolute top-3 left-3 px-3 py-1.5 bg-popover/90 text-popover-foreground text-sm rounded-md border border-border backdrop-blur-sm pointer-events-none">
          {hoverLabel}
        </div>
      ) : null}
    </div>
  );
}

export default GlobeScene;
